*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #f5f5f7;
  --color-surface:      #ffffff;
  --color-border:       #d1d5db;
  --color-border-hover: #9ca3af;
  --color-accent:       #2563eb;
  --color-accent-dark:  #1d4ed8;
  --color-accent-light: #eff6ff;
  --color-text:         #111827;
  --color-text-muted:   #4b5563;
  --color-error:        #b91c1c;
  --color-error-bg:     #fef2f2;
  --color-error-border: #fca5a5;
  --color-success:      #15803d;
  --color-success-bg:   #f0fdf4;
  --color-success-border: #86efac;
  --radius-sm:          6px;
  --radius-md:          12px;
  --radius-lg:          16px;
  --shadow-card:        0 1px 3px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
  --font:               -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --transition:         150ms ease;
}

/* ── Skip link ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font: 600 .875rem/1 var(--font);
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Page ───────────────────────────────────────────────── */
body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem 1rem;
}

/* ── Layout ─────────────────────────────────────────────── */
.page-wrapper {
  width: 100%;
  max-width: 480px;
}

header.page-header {
  text-align: center;
  margin-bottom: 2rem;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.025em;
  line-height: 1.2;
}

.page-header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .9375rem;
  line-height: 1.5;
}

/* ── Card ───────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
}

/* ── Form ───────────────────────────────────────────────── */
.settings-form {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ── Field ──────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: .25rem;
}

/* ── Fieldset / legend ──────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
  margin-bottom: .875rem;
  display: flex;
  align-items: center;
  gap: .25rem;
}

legend .required-marker {
  color: var(--color-error);
  font-size: 1.1em;
  line-height: 1;
}

/* ── Radio options ──────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    border-color var(--transition),
    background var(--transition),
    box-shadow var(--transition);
  user-select: none;
}

.radio-label:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

/* Highlight the selected card */
.radio-label:has(input:checked) {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
  box-shadow: 0 0 0 1px var(--color-accent);
}

/* ── Custom radio circle ────────────────────────────────── */
.radio-label input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  flex-shrink: 0;
  transition: border-color var(--transition), box-shadow var(--transition);
  position: relative;
  cursor: pointer;
  background: var(--color-surface);
}

.radio-label input[type="radio"]:checked {
  border-color: var(--color-accent);
  background: var(--color-accent);
  box-shadow: inset 0 0 0 3px var(--color-surface);
}

/* Focus visible — meets 3:1 boundary contrast */
.radio-label input[type="radio"]:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.radio-option-text {
  display: flex;
  flex-direction: column;
  gap: .125rem;
}

.radio-option-name {
  font-size: .9375rem;
  font-weight: 500;
  line-height: 1.4;
  color: var(--color-text);
}

.radio-option-desc {
  font-size: .8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

/* ── Error / status messages ────────────────────────────── */
.field-error {
  display: none;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  color: var(--color-error);
  padding: .5rem .75rem;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-sm);
}

.field-error[data-visible="true"] { display: flex; }

.field-error svg { flex-shrink: 0; }

/* ── Submit button ──────────────────────────────────────── */
.btn-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  width: 100%;
  padding: .875rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font: 600 1rem/1 var(--font);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  letter-spacing: -.01em;
}

.btn-submit:hover { background: var(--color-accent-dark); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  background: var(--color-accent-dark);
}

.btn-submit:active { opacity: .9; }

/* ── Status banner ──────────────────────────────────────── */
.status-banner {
  display: none;
  align-items: flex-start;
  gap: .625rem;
  padding: .875rem 1rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  line-height: 1.4;
  margin-top: .5rem;
}

.status-banner[data-type="success"] {
  display: flex;
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  color: var(--color-success);
}

.status-banner[data-type="error"] {
  display: flex;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  color: var(--color-error);
}

.status-banner svg { flex-shrink: 0; margin-top: 1px; }

/* ── Required legend ────────────────────────────────────── */
.required-legend {
  font-size: .8125rem;
  color: var(--color-text-muted);
  text-align: right;
}

/* ── Forced colors (high contrast) ─────────────────────── */
@media (forced-colors: active) {
  .radio-label { border: 2px solid ButtonText; }
  .radio-label:has(input:checked) { border-color: Highlight; background: transparent; }
  .radio-label input[type="radio"] { border-color: ButtonText; }
  .radio-label input[type="radio"]:checked {
    background: Highlight;
    border-color: Highlight;
    forced-color-adjust: none;
  }
  .btn-submit { forced-color-adjust: none; background: Highlight; color: HighlightText; }
}

/* ── Reduced motion ─────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow at 320 px ───────────────────────────────────── */
@media (max-width: 360px) {
  .card { padding: 1.25rem; }
  .radio-label { padding: .75rem; }
}
